import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        Integer bulat = 7;
        Number n = bulat;
        System.out.println(n);

        List<Number> angka = new ArrayList<>();
        angka.add(7);
        angka.add(2.5);
        System.out.println(angka);

        Number[] larik = new Integer[2];
        larik[0] = 7;
        System.out.println(larik[0]);
        try {
            larik[1] = 2.5;
            System.out.println("baris ini tidak pernah dicetak");
        } catch (ArrayStoreException e) {
            System.out.println("Gagal: " + e.getClass().getSimpleName());
        }
    }
}

