import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Number> angka = new ArrayList<>();
        angka.add(4);
        angka.add(2.5);
        System.out.println(angka);
        double total = 0;
        for (Number n : angka) {
            total += n.doubleValue();
        }
        System.out.println(total);
    }
}

